//! Option index follows the qualifying ancestor SELECT owner.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=owner><select id=select><option id=option>One</option><optgroup><option id=grouped>Two</option></optgroup></select><datalist id=choices><option id=suggestion>Suggestion</option></datalist></form><form id=other></form><select id=external form=other><option id=externalOption>External</option></select><select id=missing form=missing><option id=missingOption>Missing</option></select><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://option-index.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn option_index_canonical_readonly_descriptor_and_native_list_order(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('option'),grouped=document.getElementById('grouped'),a=Object.getOwnPropertyDescriptor(HTMLOptionElement.prototype,'index');if(!a||!a.enumerable||!a.configurable||a.set!==undefined||a.get.name!=='get index'||a.get.length!==0||Object.hasOwn(x,'index')||x.index!==0||grouped.index!==1||a.get.call(grouped)!==1||document.getElementById('externalOption').index!==0)throw 'canonical actual option index';var calls=0;grouped.index={toString:function(){calls++;return '0';}};if(grouped.index!==1||calls)throw 'readonly index no conversion';var caught=false;try{(function(){'use strict';grouped.index=0;})();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'strict readonly index';"#);}
#[test]
fn option_index_inert_live_list_insert_remove_and_actual_owner(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),html='http://www.w3.org/1999/xhtml',select=doc.createElementNS(html,'select'),first=doc.createElementNS(html,'option'),group=doc.createElementNS(html,'optgroup'),x=doc.createElementNS(html,'p:option');select.appendChild(first);select.appendChild(group);group.appendChild(x);if(first.index!==0||x.index!==1)throw 'inert initial order';var earlier=doc.createElementNS(html,'option');select.insertBefore(earlier,first);if(x.index!==2||first.index!==1||earlier.index!==0)throw 'actual insertion order';select.removeChild(first);if(x.index!==1||first.index!==0)throw 'actual removal order';select.setAttribute('form','missing');if(x.index!==1)throw 'index independent of form owner';"#);}
#[test]
fn option_index_standalone_and_datalist_do_not_count_suggestions(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"if(document.createElement('option').index!==0||document.getElementById('suggestion').index!==0)throw 'outside select zero index';var doc=new Document(),html='http://www.w3.org/1999/xhtml',list=doc.createElementNS(html,'datalist'),a=doc.createElementNS(html,'option'),b=doc.createElementNS(html,'option');list.appendChild(a);list.appendChild(b);if(list.options.length!==2||a.index!==0||b.index!==0)throw 'datalist collection is not select list';"#);}
#[test]
fn option_index_concrete_brand_and_author_override_keep_canonical_result(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('grouped'),C=HTMLOptionElement,P=C.prototype,get=Object.getOwnPropertyDescriptor(P,'index').get;for(var bad of [{},Object.create(P),document.body,document.createElement('select'),document.createElementNS('urn:foreign','option'),new Document().createElementNS('http://www.w3.org/1999/xhtml','OPTION')]){var caught=false;try{get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'index concrete brand';}Object.defineProperty(x,'index',{value:'author',configurable:true});if(x.index!=='author'||get.call(x)!==1)throw 'canonical index authority';delete x.index;delete window.HTMLOptionElement;if(!(x instanceof C)||get.call(x)!==1)throw 'saved index constructor';"#);}

#[test]
fn option_index_exact_ancestry_list_pruning_and_namespace_distinctions(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),html='http://www.w3.org/1999/xhtml',select=doc.createElementNS(html,'select');function make(parent,tag,ns){var x=doc.createElementNS(ns===undefined?html:ns,tag);parent.appendChild(x);return x;}var plain=make(make(select,'div'),'option'),group=make(select,'optgroup'),one=make(make(group,'div'),'option'),two=make(make(group,'optgroup'),'option'),list=make(make(select,'datalist'),'option'),rule=make(make(select,'hr'),'option'),nested=make(make(select,'option'),'option'),inner=make(make(select,'select'),'option'),foreign=make(make(select,'datalist','urn:foreign'),'option'),upper=make(make(select,'OPTGROUP'),'option');if(plain.index!==0||one.index!==1||foreign.index!==3||upper.index!==4)throw 'exact qualifying option order';for(var x of [two,list,rule,nested,inner])if(x.index!==0)throw 'excluded option list';"#);}
#[test]
fn option_index_native_work_copy_storage_deadline_refusal_and_string_free_recovery(){for mode in 0..5{let(mut d,mut f,mut p)=fixture();let n=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("grouped")).unwrap();p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.execution_deadline=Some(Instant::now()),2=>p.state.copy_work=0,3=>p.state.retained_limit=p.state.retained,_=>p.state.limits.host.string_bytes=0};let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.option_index_get(node_handle(n));if mode==4{assert!(matches!(result,Ok(Value::Number(n))if n==1.0));}else{let e=result.unwrap_err();assert!(e.contains("work")||e.contains("time")||e.contains("allowance")||e.contains("limit"),"{e}");}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();assert!(matches!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.option_index_get(node_handle(n)).unwrap(),Value::Number(n)if n==1.0));}}
#[test]
fn option_index_inert_refusal_keeps_live_order_and_observer_records(){for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var doc=new Document(),html='http://www.w3.org/1999/xhtml',select=doc.createElementNS(html,'select'),first=doc.createElementNS(html,'option'),x=doc.createElementNS(html,'option');select.appendChild(first);select.appendChild(x);var watch=new MutationObserver(function(){});watch.observe(select,{attributes:true,childList:true,subtree:true});if(x.index!==1)throw 'initial live order';");let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.execution_deadline=Some(Instant::now()),2=>p.state.copy_work=0,_=>p.state.retained_limit=p.state.retained};let e=p.runtime.execute("x.index;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("time")||e.contains("allowance")||e.contains("limit"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.retained_limit=limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(x.index!==1||watch.takeRecords().length)throw 'fresh index recovery';select.removeChild(first);if(x.index!==0||first.index!==0||watch.takeRecords().length!==1)throw 'fresh list removal';");}}
#[test]
fn option_index_saved_child_origin_precedes_list_reads_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('grouped'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var get=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLOptionElement.prototype,'index').get;if(get.call(x)!==1)throw 'same origin index';");p.set_location(&crate::navigation::address("https://other-option-index.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits);p.begin_job();let e=p.runtime.execute("get.call(x);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),state);p.set_location(&crate::navigation::address("https://option-index.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(get.call(x)!==1)throw 'saved index recovery';");}
